import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0002 (Remaining): Plugin Library Conversion and Module Abstraction","description":"","frontmatter":{"title":"ADR-0002 (Remaining): Plugin Library Conversion and Module Abstraction","type":"adr","date":"2026-08-29T00:00:00.000Z","status":"proposed","status_note":"Proposed"},"headers":[],"relativePath":"handl/project/adrs/0002-handl-platform-composable-host-remaining.md","filePath":"vendored/handl/project/adrs/0002-handl-platform-composable-host-remaining.md"}`),a={name:`handl/project/adrs/0002-handl-platform-composable-host-remaining.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0002-remaining-plugin-library-conversion-and-module-abstraction" tabindex="-1">ADR-0002 (Remaining): Plugin Library Conversion and Module Abstraction <a class="header-anchor" href="#adr-0002-remaining-plugin-library-conversion-and-module-abstraction" aria-label="Permalink to “ADR-0002 (Remaining): Plugin Library Conversion and Module Abstraction”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Complete the conversion of the remaining <code>plugin-lib-*</code> crates to work cleanly within the unified plugin model. Key questions to resolve:</p><ol><li><p><em><em>Should plugin-lib-</em> crates use Behavior&lt;Op&gt; or is Module/Function the appropriate abstraction for host-exported functions?</em>*</p><ul><li>Current state: ~20+ plugin-lib-* crates use <code>Module</code> trait and expose <code>Function</code> values for handl code to call</li><li>Option A: Convert to <code>Behavior&lt;Op&gt;</code> (one operation per library capability)</li><li>Option B: Keep <code>Module/Function</code> as the abstraction for &quot;host functions that handl code calls&quot; (distinct from rule contributions)</li><li>Option C: Hybrid — use <code>Module</code> as an adapter that contributes <code>Behavior&lt;Op&gt;</code> to the appropriate operations</li></ul></li><li><p><strong>How should library dependencies be expressed?</strong></p><ul><li>Can a plugin-lib-* declare that it requires or provides specific module capabilities?</li><li>Should this be done via <code>Plugin::depends_on()</code> trait or via a separate dependency manifest?</li></ul></li><li><p><strong>What about library options?</strong></p><ul><li>How do plugin-lib-* register options (e.g., compression level, timeout) if not via the legacy <code>Library::options()</code>?</li><li>Should the <code>OptionsPlugin</code> be extended to support library-scoped options?</li></ul></li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>ADR-0002 v1 (Single Plugin Model for Host, Operations, Libraries, Targets, and Options) has been implemented and archived. The core architecture is complete: <code>Plugin</code>, <code>RuleAcceptor</code>, <code>Behavior&lt;Op&gt;</code>, and the removal of <code>Extension</code>/<code>CommandProvider</code>/<code>Library</code> legacy traits are done. The host is now a pure composer with no hard-coded stage wiring.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>plugin-lib-* crates become clean participants in the unified plugin model, not legacy holdovers.</li><li>Library behavior can be tested, mocked, and composed like all other plugin behavior.</li><li>The platform/host contains no special-case logic for libraries.</li><li>Kit manifests can be fully audited and composed without hidden library dependencies.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>plugin-lib-*</code> — where this is true.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0002-handl-platform-composable-host-remaining.html"><code>design/0002-handl-platform-composable-host-remaining.md</code></a>.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};